#include <tlhelp32.h>
#include <math.h>
#include <stdio.h>

typedef struct { DWORD pid; HANDLE h; uintptr_t base; } Target;

static Target T = {0, NULL, 0};

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe = { .dwSize = sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me = { .dwSize = sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (_wcsicmp(me.szModule, mod) == 0) { base = (uintptr_t)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

static int RPM(uintptr_t addr, void* buf, size_t n) {
    SIZE_T got = 0;
    return ReadProcessMemory(T.h, (LPCVOID)addr, buf, n, &got) && got == n;
}

static int WPM(uintptr_t addr, const void* buf, size_t n) {
    SIZE_T put = 0;
    return WriteProcessMemory(T.h, (LPVOID)addr, buf, n, &put) && put == n;
}

// 多级指针链解析：offsets 从顶层基址 + 偏移依次解引用
static uintptr_t ResolveChain(uintptr_t base, const uint32_t* offsets, int n) {
    uintptr_t cur = base;
    for (int i = 0; i < n; i++) {
        if (!RPM(cur + offsets[i], &cur, sizeof(cur))) return 0;
        if (!cur) return 0;
    }
    return cur;
}

