// 用 MmCopyVirtualMemory 完成跨进程读写（内核态调用，不触发用户态 OpenProcess 审计）
static NTSTATUS KvCopy(ULONG pid, ULONG64 addr, PVOID buf, ULONG size, BOOLEAN write)
{
    PEPROCESS src = NULL, dst = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, &src);
    if (!NT_SUCCESS(st)) return st;

    dst = PsGetCurrentProcess();
    SIZE_T done = 0;
    KAPC_STATE apc;
    KeStackAttachProcess(src, &apc);   // 切到目标进程地址空间
    if (write)
        st = MmCopyVirtualMemory(dst, buf, src, (PVOID)(ULONG_PTR)addr, size, KernelMode, &done);
    else
        st = MmCopyVirtualMemory(src, (PVOID)(ULONG_PTR)addr, dst, buf, size, KernelMode, &done);
    KeUnstackDetachProcess(&apc);

    ObDereferenceObject(src);
    return st;
}

// MDL 方式：手动锁页映射，绕过 MmCopyVirtualMemory 内部对目标进程 Attach 的痕迹
static NTSTATUS MdlRead(ULONG pid, ULONG64 addr, PVOID out, ULONG size)
{
    PEPROCESS proc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, &proc);
    if (!NT_SUCCESS(st)) return st;

    KAPC_STATE apc;
    KeStackAttachProcess(proc, &apc);

    PMDL mdl = IoAllocateMdl((PVOID)(ULONG_PTR)addr, size, FALSE, FALSE, NULL);
    if (!mdl) { KeUnstackDetachProcess(&apc); ObDereferenceObject(proc); return STATUS_INSUFFICIENT_RESOURCES; }

    __try {
        MmProbeAndLockPages(mdl, UserMode, IoReadAccess);
        PVOID map = MmGetSystemAddressForMdlSafe(mdl, NormalPagePriority);
        if (map) RtlCopyMemory(out, map, size);
        MmUnlockPages(mdl);
        st = map ? STATUS_SUCCESS : STATUS_UNSUCCESSFUL;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        st = GetExceptionCode();
    }

    IoFreeMdl(mdl);
    KeUnstackDetachProcess(&apc);
    ObDereferenceObject(proc);
    return st;
}

