NTSTATUS ReadProcMem(ULONG pid, PVOID addr, PVOID buf, SIZE_T size) {
    PEPROCESS ep = NULL;
    KAPC_STATE apc;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, &ep);
    if (!NT_SUCCESS(st)) return st;
    __try {
        KeStackAttachProcess(ep, &apc);
        ProbeForRead(addr, size, 1);
        RtlCopyMemory(buf, addr, size);
        KeUnstackDetachProcess(&apc);
    } __except (EXCEPTION_EXECUTE_HANDLER) { st = STATUS_ACCESS_VIOLATION; }
    ObDereferenceObject(ep);
    return st;
}

NTSTATUS WriteProcMem(ULONG pid, PVOID addr, PVOID buf, SIZE_T size) {
    PEPROCESS ep = NULL;
    KAPC_STATE apc;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, &ep);
    if (!NT_SUCCESS(st)) return st;
    __try {
        KeStackAttachProcess(ep, &apc);
        ProbeForWrite(addr, size, 1);
        RtlCopyMemory(addr, buf, size);
        KeUnstackDetachProcess(&apc);
    } __except (EXCEPTION_EXECUTE_HANDLER) { st = STATUS_ACCESS_VIOLATION; }
    ObDereferenceObject(ep);
    return st;
}

