NTSTATUS DispatchIoctl(PDEVICE_OBJECT dev, PIRP irp) {
    UNREFERENCED_PARAMETER(dev);
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    PVOID sys = irp->AssociatedIrp.SystemBuffer;
    NTSTATUS st = STATUS_INVALID_PARAMETER;
    ULONG info = 0;

    if (sp->Parameters.DeviceIoControl.InputBufferLength >= sizeof(RW_REQ)) {
        PRW_REQ r = (PRW_REQ)sys;
        // 用 MmCopyVirtualMemory 替代 Attach，避免 KiStackAttach 被 ETW-TI 抓到
        PEPROCESS src = NULL, dst = NULL;
        if (NT_SUCCESS(PsLookupProcessByProcessId(PsGetCurrentProcessId(), &dst)) &&
            NT_SUCCESS(PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)r->Pid, &src))) {
            SIZE_T copied = 0;
            switch (sp->Parameters.DeviceIoControl.IoControlCode) {
            case IOCTL_READ:
                st = MmCopyVirtualMemory(src, r->Addr, dst, r->Buffer, r->Size, UserMode, &copied);
                info = (ULONG)copied; break;
            case IOCTL_WRITE:
                st = MmCopyVirtualMemory(dst, r->Buffer, src, r->Addr, r->Size, UserMode, &copied);
                info = (ULONG)copied; break;
            }
            ObDereferenceObject(src);
        }
        if (dst) ObDereferenceObject(dst);
    }
    irp->IoStatus.Status = st;
    irp->IoStatus.Information = info;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

