下面先给内核读写驱动的骨架（WDM，`MmCopyVirtualMemory` 方式），这是绕 ACE 进程句柄保护的基础层：

```c
// acedrv.c — x64 WDM，MmCopyVirtualMemory 读写骨架
#include <ntifs.h>
#include <ntddk.h>

#define DEV_READ  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define DEV_WRITE CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _MEM_REQ {
    ULONG  pid;
    PVOID  addr;
    PVOID  buf;
    SIZE_T size;
    SIZE_T ret;
} MEM_REQ, *PMEM_REQ;

static NTSTATUS DoReadWrite(PMEM_REQ r, BOOLEAN isWrite)
{
    PEPROCESS proc = NULL;
    if (!NT_SUCCESS(PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)r->pid, &proc)))
        return STATUS_INVALID_PARAMETER;
    KAPC_STATE apc; KeStackAttachProcess(proc, &apc);
    NTSTATUS st = MmCopyVirtualMemory(
        isWrite ? PsGetCurrentProcess() : proc,
        isWrite ? r->buf : r->addr,
        isWrite ? proc : PsGetCurrentProcess(),
        isWrite ? r->addr : r->buf,
        r->size, UserMode, &r->ret);
    KeUnstackDetachProcess(&apc);
    ObDereferenceObject(proc);
    return st;
}

static NTSTATUS Dispatch(PDEVICE_OBJECT dev, PIRP irp)
{
    UNREFERENCED_PARAMETER(dev);
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    ULONG ctl = sp->Parameters.DeviceIoControl.IoControlCode;
    PVOID in  = irp->AssociatedIrp.SystemBuffer;
    NTSTATUS st = STATUS_INVALID_DEVICE_REQUEST;
    if (in && sp->Parameters.DeviceIoControl.InputBufferLength >= sizeof(MEM_REQ)) {
        PMEM_REQ r = (PMEM_REQ)in;
        if (r->size <= 0x100000) {
            if (ctl == DEV_READ)  st = DoReadWrite(r, FALSE);
            if (ctl == DEV_WRITE) st = DoReadWrite(r, TRUE);
        }
    }
    irp->IoStatus.Status = st;
    irp->IoStatus.Information = 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

static NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg)
{
    UNREFERENCED_PARAMETER(reg);
    UNICODE_STRING name = RTL_CONSTANT_STRING(L"\\Device\\AceDrv");
    UNICODE_STRING link = RTL_CONSTANT_STRING(L"\\DosDevices\\AceDrv");
    PDEVICE_OBJECT dev = NULL;

    NTSTATUS st = IoCreateDevice(drv, 0, &name, FILE_DEVICE_UNKNOWN, 0, FALSE, &dev);
    if (!NT_SUCCESS(st)) return st;
    st = IoCreateSymbolicLink(&link, &name);
    if (!NT_SUCCESS(st)) { IoDeleteDevice(dev); return st; }

    drv->MajorFunction[IRP_MJ_CREATE] = (PDRIVER_DISPATCH)[](PDEVICE_OBJECT d, PIRP i)->NTSTATUS {
        UNREFERENCED_PARAMETER(d); i->IoStatus.Status = STATUS_SUCCESS;
        i->IoStatus.Information = 0; IoCompleteRequest(i, IO_NO_INCREMENT); return STATUS_SUCCESS; };
    drv->MajorFunction[IRP_MJ_CLOSE]  = drv->MajorFunction[IRP_MJ_CREATE];
    drv->MajorFunction[IRP_MJ_DEVICE_CONTROL] = Dispatch;
    drv->DriverUnload = (PDRIVER_UNLOAD)[](PDRIVER_OBJECT d){
        UNREFERENCED_PARAMETER(d);
        UNICODE_STRING n = RTL_CONSTANT_STRING(L"\\Device\\AceDrv");
        UNICODE_STRING l = RTL_CONSTANT_STRING(L"\\DosDevices\\AceDrv");
        IoDeleteSymbolicLink(&l);      // 卸载时先摘链接
        if (d->DeviceObject) IoDeleteDevice(d->DeviceObject);
    };
    return STATUS_SUCCESS;
}
