```cpp
// detect_surface.cpp — 枚举当前进程所有句柄，看谁在开我们（Windows x64）
// 编译：cl /EHsc /std:c++17 detect_surface.cpp
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <cstdio>
#pragma comment(lib, "psapi.lib")

int main(int argc, char** argv) {
    DWORD pid = (DWORD)atoi(argv[1]);            // 目标进程 PID
    HANDLE h = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    if (!h) { printf("OpenProcess failed: %lu\n", GetLastError()); return 1; }

    // 1) 模块枚举——反作弊通常先枚举这些模块名做黑名单
    HMODULE mods[1024]; DWORD need = 0;
    if (EnumProcessModulesEx(h, mods, sizeof(mods), &need, LIST_MODULES_ALL)) {
        for (DWORD i = 0; i < need / sizeof(HMODULE); i++) {
            char name[MAX_PATH] = {0};
            GetModuleBaseNameA(h, mods[i], name, MAX_PATH);
            printf("MODULE %p %s\n", (void*)mods[i], name);
        }
    }

    // 2) 内存区域枚举——找 RWX 私有区（注入模块、shellcode 藏身处）
    MEMORY_BASIC_INFORMATION mbi; BYTE* addr = 0;
    while (VirtualQueryEx(h, addr, &mbi, sizeof(mbi)) == sizeof(mbi)) {
        if (mbi.Type == MEM_PRIVATE && (mbi.Protect & (PAGE_EXECUTE_READWRITE | PAGE_EXECUTE_READ))) {
            printf("SUSPECT %p size=0x%llx prot=0x%lx\n",
                   mbi.BaseAddress, (unsigned long long)mbi.RegionSize, mbi.Protect);
        }
        addr = (BYTE*)mbi.BaseAddress + mbi.RegionSize;
        if (addr < (BYTE*)mbi.BaseAddress) break;
    }
    CloseHandle(h);
    return 0;
}
```

