### 第一步：读写模块（用户态，最小可跑）

```cpp
#include <windows.h>
#include <TlHelp32.h>
#include <cstdint>
#include <vector>
#include <string>

class Memory {
    HANDLE hProcess = nullptr;
public:
    bool Attach(const wchar_t* procName) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        PROCESSENTRY32W pe{ sizeof(pe) };
        DWORD pid = 0;
        if (Process32FirstW(snap, &pe)) {
            do {
                if (_wcsicmp(pe.szExeFile, procName) == 0) { pid = pe.th32ProcessID; break; }
            } while (Process32NextW(snap, &pe));
        }
        CloseHandle(snap);
        if (!pid) return false;
        hProcess = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
        return hProcess != nullptr;
    }

    template<typename T> T Read(uintptr_t addr) {
        T val{};
        ReadProcessMemory(hProcess, reinterpret_cast<LPCVOID>(addr), &val, sizeof(T), nullptr);
        return val;
    }

    template<typename T> bool Write(uintptr_t addr, T val) {
        return WriteProcessMemory(hProcess, reinterpret_cast<LPVOID>(addr), &val, sizeof(T), nullptr) != 0;
    }

    uintptr_t GetModuleBase(const wchar_t* modName) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, GetProcessId(hProcess));
        MODULEENTRY32W me{ sizeof(me) };
        uintptr_t base = 0;
        if (Module32FirstW(snap, &me)) {
            do {
                if (_wcsicmp(me.szModule, modName) == 0) { base = reinterpret_cast<uintptr_t>(me.modBaseAddr); break; }
            } while (Module32NextW(snap, &me));
        }
        CloseHandle(snap);
        return base;
    }
};
```

