// 4) 在内核里定位 BE 的进程/镜像回调，摘掉对目标进程的通知
// 先枚举 PsSetCreateProcessNotifyRoutineEx 注册的回调，找到 BE 驱动的那一个
#include <ntddk.h>

typedef struct _EX_CALLBACK_ROUTINE_BLOCK {
    EX_RUNDOWN_REF RundownRef;
    LIST_ENTRY      List;
    PVOID           Function;
    PVOID           Context;
} EX_CALLBACK_ROUTINE_BLOCK, *PEX_CALLBACK_ROUTINE_BLOCK;

#define MAX_PROC_NOTIFY 64
NTSTATUS RemoveBeProcessNotify(PVOID BeNotifyRoutine)
{
    PEX_CALLBACK_ROUTINE_BLOCK block;
    ULONG_PTR routineTable;
    ULONG i;
    NTSTATUS st = STATUS_NOT_FOUND;

    // PsSetCreateProcessNotifyRoutineEx 的回调表
    routineTable = *(ULONG_PTR*)((PUCHAR)&PsSetCreateProcessNotifyRoutineEx + 0x1A) ;
    // 偏移按你本机 ntoskrnl 版本实测修正，上面只是入口点解析写法
    for (i = 0; i < MAX_PROC_NOTIFY; i++) {
        ULONG_PTR entry;
        ProbeForRead((PVOID)(routineTable + i * sizeof(ULONG_PTR)),
                     sizeof(ULONG_PTR), sizeof(ULONG_PTR));
        entry = *(ULONG_PTR*)(routineTable + i * sizeof(ULONG_PTR));
        entry &= ~0xF;   // 去掉 low bits（回调标志位）
        if (!entry) continue;
        block = (PEX_CALLBACK_ROUTINE_BLOCK)entry;
        if (block->Function == BeNotifyRoutine) {
            // 原子地清空，令内核不再回调 BE
            InterlockedExchangePointer((PVOID*)&block->Function, NULL);
            st = STATUS_SUCCESS;
            break;
        }
    }
    return st;
}
