// ace_probe_01.cpp —— 只做一件事：确认 ACE 驱动在不在、拦不拦 OpenProcess
// 编译: cl /EHsc /std:c++17 ace_probe_01.cpp /link Psapi.lib
#include <windows.h>
#include <psapi.h>
#include <cstdio>
#include <vector>
#include <string>

static void dump_proc_modules(DWORD pid) {
    HANDLE h = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    if (!h) { printf("[!] OpenProcess(PROCESS_VM_READ) failed pid=%lu err=%lu\n", pid, GetLastError()); return; }
    HMODULE mods[1024]; DWORD need = 0;
    if (EnumProcessModulesEx(h, mods, sizeof(mods), &need, LIST_MODULES_ALL)) {
        for (DWORD i = 0; i < need / sizeof(HMODULE); ++i) {
            char path[MAX_PATH] = {0}; char base[MAX_PATH] = {0};
            GetModuleBaseNameA(h, mods[i], base, MAX_PATH);
            GetModuleFileNameExA(h, mods[i], path, MAX_PATH);
            printf("  [%p] %s\n", (void*)mods[i], base);
        }
    }
    CloseHandle(h);
}

int main(int argc, char** argv) {
    // 用法: ace_probe_01.exe [进程名]  缺省按占位符 [进程名]
    const char* procName = (argc > 1) ? argv[1] : "[进程名]";
    printf("[*] target = %s\n", procName);

    // 1) 枚举 ACE 相关驱动/服务 —— 驱动在不在决定后续走内核态还是纯用户态
    const char* aceDrivers[] = {
        "ACE-BASE.sys", "ACE-GAME.sys", "ACE-TRAY.exe",
        "ACE-Guard Client.sys", "AceGame.sys", "AntiCheatExpert.sys",
        "SGuard64.exe", "SGuardSvc64.exe", "Guard64.exe", "GuardSvc64.exe"
    };
    for (auto d : aceDrivers) {
        SC_HANDLE scm = OpenSCManagerA(NULL, NULL, SC_MANAGER_ENUMERATE_SERVICE);
        if (!scm) break;
        SC_HANDLE svc = OpenServiceA(scm, d, SERVICE_QUERY_STATUS);
        if (svc) {
            SERVICE_STATUS st = {0};
            QueryServiceStatus(svc, &st);
            printf("[+] service FOUND: %s state=0x%08lX\n", d, st.dwCurrentState);
            CloseServiceHandle(svc);
        }
        CloseServiceHandle(scm);
    }

    // 2) 枚举进程，找目标 + 找 ACE 用户态守护
    DWORD pids[4096], got = 0;
    if (EnumProcesses(pids, sizeof(pids), &got)) {
        for (DWORD i = 0; i < got / sizeof(DWORD); ++i) {
            HANDLE h = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pids[i]);
            if (!h) continue;
            char name[MAX_PATH] = {0}; DWORD sz = MAX_PATH;
            if (QueryFullProcessImageNameA(h, 0, name, &sz)) {
                std::string n(name);
                auto slash = n.find_last_of("\\/");
                std::string base = (slash == std::string::npos) ? n : n.substr(slash + 1);
                if (base == procName) {
                    printf("[+] TARGET pid=%lu path=%s\n", pids[i], name);
                    dump_proc_modules(pids[i]);
                }
                if (base.find("SGuard") != std::string::npos ||
                    base.find("ACE-") != std::string::npos ||
                    base.find("Guard64") != std::string::npos)
                    printf("[!] ACE user-mode guard: pid=%lu %s\n", pids[i], base.c_str());
            }
            CloseHandle(h);
        }
    }
    return 0;
}
