```c
#include <ntifs.h>
#include <ntddk.h>
#include <intrin.h>

// 物理内存基址（MmGetPhysicalMemoryRanges 可得，简化用 0）
PUCHAR g_PhysBase = 0;

// 取当前进程 CR3（非 hypervisor 下有效）
_IRQL_requires_max_(DISPATCH_LEVEL)
ULONG64 GetCr3(UINT32 pid)
{
    PEPROCESS proc = NULL;
    if (NT_SUCCESS(PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, &proc))) {
        ULONG64 cr3 = *(ULONG64*)((PUCHAR)proc + 0x28); // KPROCESS.DirectoryTableBase，Win10/11 x64 偏移
        ObDereferenceObject(proc);
        return cr3 & ~0xFFFULL;
    }
    return 0;
}

// 用物理地址直接读（关中断 + 用 MmCopyMemory 的 Physical 分支最稳）
_IRQL_requires_max_(DISPATCH_LEVEL)
NTSTATUS PhysRead(ULONG64 phys, PVOID buf, SIZE_T size)
{
    PHYSICAL_ADDRESS pa;
    pa.QuadPart = phys;
    return MmCopyMemory(buf, pa, size, MM_COPY_MEMORY_PHYSICAL, NULL);
}

_IRQL_requires_max_(DISPATCH_LEVEL)
NTSTATUS PhysWrite(ULONG64 phys, PVOID buf, SIZE_T size)
{
    // MmCopyMemory 不支持写，走 MDL 映射
    PHYSICAL_ADDRESS pa;
    pa.QuadPart = phys;
    PMDL mdl = MmMapIoSpaceEx(pa, size, PAGE_READWRITE);
    if (!mdl) return STATUS_UNSUCCESSFUL;
    RtlCopyMemory((PUCHAR)mdl, buf, size);
    MmUnmapIoSpace(mdl, size);
    return STATUS_SUCCESS;
}
```

## 二、虚拟地址 → 物理地址（CR3 页表遍历）

```c
// 4 级页表遍历（Win10/11 x64，未开 5 级）
_IRQL_requires_max_(DISPATCH_LEVEL)
ULONG64 VaToPa(ULONG64 cr3, ULONG64 va)
{
    ULONG64 pml4 = cr3;
    ULONG64 e;

    // PML4
    if (!NT_SUCCESS(PhysRead(pml4 + 8 * ((va >> 39) & 0x1FF), &e, 8))) return 0;
    if (!(e & 1)) return 0;
    ULONG64 pdpt = e & 0x000FFFFFFFFFF000ULL;

    // PDPT，处理 1GB 大页
    if (!NT_SUCCESS(PhysRead(pdpt + 8 * ((va >> 30) & 0x1FF), &e, 8))) return 0;
    if (!(e & 1)) return 0;
    if (e & 0x80) return (e & 0x000FFFFFC0000000ULL) + (va & 0x3FFFFFFF);

    ULONG64 pd = e & 0x000FFFFFFFFFF000ULL;
    // PD，处理 2MB 大页
    if (!NT_SUCCESS(PhysRead(pd + 8 * ((va >> 21) & 0x1FF), &e, 8))) return 0;
    if (!(e & 1)) return 0;
    if (e & 0x80) return (e & 0x000FFFFFFFE00000ULL) + (va & 0x1FFFFF);

    ULONG64 pt = e & 0x000FFFFFFFFFF000ULL;
    // PT
    if (!NT_SUCCESS(PhysRead(pt + 8 * ((va >> 12) & 0x1FF), &e, 8))) return 0;
    if (!(e & 1)) return 0;

    return (e & 0x000FFFFFFFFFF000ULL) + (va & 0xFFF);
}
