---

## 1. 核心：CR3 切换与物理地址映射

```c
// cr3.h
#pragma once
#include <ntifs.h>
#include <intrin.h>

typedef struct _CR3_CTX {
    UINT64      DirBase;      // 目标进程 CR3 物理地址（去掉低 12 位标志）
    PEPROCESS   Process;
    HANDLE      Pid;
} CR3_CTX, *PCR3_CTX;

// 取进程 CR3：KPROCESS.DirectoryTableBase
// Win10 1809+ 偏移 0x028；Win11 22H2+ 0x028；老版本 0x028（KPROCESS 头）
// 未验证时用 PsGetProcessPcb + 动态定位，见下方 ResolveDirBase
#define KPROCESS_DIRECTORY_TABLE_BASE 0x028

static UINT64 ReadProcessDirBase(PEPROCESS Process)
{
    // 推荐：用未导出的 KPROCESS 偏移；或直接 __readcr3() 仅在当前上下文
    PUCHAR pcb = (PUCHAR)Process;          // PEPROCESS 前部就是 KPROCESS
    UINT64 dirBase = *(UINT64*)(pcb + KPROCESS_DIRECTORY_TABLE_BASE);
    return dirBase & ~0xFFFull;            // 清低 12 位 PCID/标志
}
```

**关键点**：`_KPROCESS.DirectoryTableBase` 的偏移随版本变化。稳妥做法是 `static` 角色先在目标版本 `ntoskrnl.exe` 里用 PDB 或特征码定位，再喂给这里。占位 `[KPROCESS_DIRBASE_OFFSET]`。

---

## 2. 物理地址 → 虚拟地址映射（内核可用区）

```c
// 用 MmMapIoSpaceEx 映射物理页；或用 MDL + MmMapLockedPagesSpecifyCache
static PVOID MapPhysicalPage(UINT64 PhysAddr, SIZE_T Size)
{
    // 物理地址 4KB 边界对齐
    UINT64 aligned = PhysAddr & ~0xFFFull;
    SIZE_T pageOff = (SIZE_T)(PhysAddr & 0xFFF);
    SIZE_T mapSize = PAGE_SIZE;            // 单页，跨页再算

    PHYSICAL_ADDRESS pa;
    pa.QuadPart = (LONGLONG)aligned;

    PVOID va = MmMapIoSpaceEx(pa, mapSize, PAGE_READWRITE | PAGE_NOCACHE);
    if (!va) return NULL;
    return (PUCHAR)va + pageOff;
}

static void UnmapPhysicalPage(PVOID Base)
{
    UINT64 aligned = (UINT64)Base & ~0xFFFull;
    MmUnmapIoSpace((PVOID)aligned, PAGE_SIZE);
}
```

> 生产版要按 `Size` 跨页映射（`MmMapIoSpaceEx` 一次跨多页也可以，但要注意非连续物理页）。演示骨架先单页。

