## 3. 手动走页表（用目标 CR3）

```c
// 按 x64 4 级页表：PML4 -> PDPT -> PD -> PT
static UINT64 TranslateVA(UINT64 DirBase, UINT64 Va)
{
    UINT64 offPml4 = (Va >> 39) & 0x1FF;
    UINT64 offPdpt = (Va >> 30) & 0x1FF;
    UINT64 offPd   = (Va >> 21) & 0x1FF;
    UINT64 offPt   = (Va >> 12) & 0x1FF;
    UINT64 pageOff = Va & 0xFFF;

    UINT64 pml4e = 0, pdpte = 0, pde = 0, pte = 0;

    // 读 PML4E：[DirBase + offPml4*8]
    PVOID p = MapPhysicalPage(DirBase + offPml4 * 8, 8);
    if (!p) return 0;
    pml4e = *(UINT64*)p; UnmapPhysicalPage(p);
