```cpp
// rw.cpp — 用户态读写骨架，MSVC x64 / /std:c++17
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>
#include <string>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (_wcsicmp(me.szModule, mod) == 0) { base = (uintptr_t)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

int wmain() {
    const wchar_t* PROC = L"[进程名].exe";
    const wchar_t* MOD  = L"[模块名].exe";

    DWORD pid = FindPid(PROC);
    if (!pid) { wprintf(L"pid not found\n"); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed %lu\n", GetLastError()); return 1; }

    uintptr_t base = GetModuleBase(pid, MOD);
    wprintf(L"pid=%lu base=0x%llX\n", pid, (unsigned long long)base);

    // 多级指针链：base + [偏移1] -> +[偏移2] -> ... -> 目标值
    std::vector<uintptr_t> chain = { 0x[偏移1], 0x[偏移2], 0x[偏移3] };
    uintptr_t addr = base;
    for (size_t i = 0; i < chain.size(); ++i) {
        uintptr_t next = 0;
        if (!ReadProcessMemory(h, (LPCVOID)(addr + chain[i]), &next, sizeof(next), nullptr)) {
            wprintf(L"RPM fail at level %zu\n", i); return 1;
        }
        addr = next;
    }

    int oldVal = 0;
    ReadProcessMemory(h, (LPCVOID)addr, &oldVal, sizeof(oldVal), nullptr);
    wprintf(L"addr=0x%llX old=%d\n", (unsigned long long)addr, oldVal); // 先 dump 原值

    int newVal = [目标值];
    WriteProcessMemory(h, (LPVOID)addr, &newVal, sizeof(newVal), nullptr);

    int check = 0;
    ReadProcessMemory(h, (LPCVOID)addr, &check, sizeof(check), nullptr);
    wprintf(L"after=%d\n", check);

    CloseHandle(h);
    return 0;
}
```

