```cpp
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <cstdio>

// [进程名] 换成目标，如 L"GameClient.exe"
const wchar_t* TARGET_PROC = L"[进程名]";

int main() {
    // 1. 取 PID
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    while (Process32NextW(snap, &pe)) {
        if (_wcsicmp(pe.szExeFile, TARGET_PROC) == 0) { pid = pe.th32ProcessID; break; }
    }
    CloseHandle(snap);
    if (!pid) { printf("process not found\n"); return 1; }

    // 2. 打开进程（加 SeDebugPrivilege 才能对受保护进程生效）
    HANDLE hProc = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE |
                               PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION,
                               FALSE, pid);
    if (!hProc) { printf("OpenProcess failed: %lu\n", GetLastError()); return 1; }

    // 3. 枚举模块取基址：先拿主模块，再按 [模块名] 精确定位
    HMODULE mods[1024]; DWORD needed;
    if (!EnumProcessModulesEx(hProc, mods, sizeof(mods), &needed, LIST_MODULES_ALL)) {
        printf("EnumProcessModulesEx failed: %lu\n", GetLastError()); return 1;
    }
    int n = needed / sizeof(HMODULE);
    for (int i = 0; i < n; i++) {
        wchar_t name[MAX_PATH];
        if (GetModuleBaseNameW(hProc, mods[i], name, MAX_PATH))
            wprintf(L"module: %s base=0x%llX size=0x%X\n", name,
                    (unsigned long long)mods[i],
                    ((IMAGE_NT_HEADERS*)((BYTE*)mods[i] +
                     ((IMAGE_DOS_HEADER*)mods[i])->e_lfanew))->OptionalHeader.SizeOfImage);
    }

    // 4. 基址 + 多级偏移链读值：[基址偏移] -> [偏移1] -> [偏移2] -> ...
    uintptr_t base = (uintptr_t)mods[0];      // 或按模块名挑出 [模块名] 的基址
    uintptr_t addr = base + [基址偏移];        // 占位符，逆向出来的偏移填这
    const uintptr_t chain[] = { [偏移1], [偏移2], [偏移3] };
    for (uintptr_t off : chain) {
        uintptr_t next = 0;
        ReadProcessMemory(hProc, (LPCVOID)addr, &next, sizeof(next), nullptr);
        if (!next) { printf("chain broken at 0x%llX\n", (unsigned long long)addr); return 1; }
        addr = next + off;
    }

    // 5. 读目标值，改之前先把原值 dump 留回滚
    int value = 0;
    ReadProcessMemory(hProc, (LPCVOID)addr, &value, sizeof(value), nullptr);
    printf("addr=0x%llX value=%d (orig dumped)\n", (unsigned long long)addr, value);
    // WriteProcessMemory(hProc, (LPCVOID)addr, &newValue, sizeof(newValue), nullptr);

    CloseHandle(hProc);
    return 0;
}
```

