## 3. 世界中转屏幕（W2S 核心，矩阵来自上表）

```cpp
struct Matrix4x4 { float m[4][4]; };

bool WorldToScreen(const Matrix4x4& vm, const float pos[3], float out[2],
                   int w, int h) {
    float clipW = vm.m[3][0]*pos[0] + vm.m[3][1]*pos[1] + vm.m[3][2]*pos[2] + vm.m[3][3];
    if (clipW < 0.01f) return false;
    float clipX = vm.m[0][0]*pos[0] + vm.m[0][1]*pos[1] + vm.m[0][2]*pos[2] + vm.m[0][3];
    float clipY = vm.m[1][0]*pos[0] + vm.m[1][1]*pos[1] + vm.m[1][2]*pos[2] + vm.m[1][3];
    float ndcX = clipX / clipW, ndcY = clipY / clipW;
    out[0] = (w * 0.5f) * (1.f + ndcX);
    out[1] = (h * 0.5f) * (1.f - ndcY);
    return true;
}
```

## 4. 角度计算 + 平滑（锁头核心）

```cpp
float Deg2Rad = 3.14159265f / 180.f;
void CalcAngle(const float src[3], const float dst[3], float angles[2]) {
    float d[3] = { dst[0]-src[0], dst[1]-src[1], dst[2]-src[2] };
    float hyp = sqrtf(d[0]*d[0] + d[1]*d[1]);
    angles[1] = atanf(d[1] / hyp) / Deg2Rad;            // Pitch
    angles[0] = atanf(d[0] / d[2]) / Deg2Rad;            // Yaw
}
```

